clause = #{b.clause}, reason = #{b.reason}, listed_at = #{b.listedAt}, expire_at = #{b.expireAt}, notify_time = #{b.notifyTime}, status = #{b.status}, operator_id = #{b.operatorId}, updated_at = NOW()
